// Cloud Seeder Fleet - terraforming timeline estimator (Mark 1 demonstration run)
// Run with: node demo.js
'use strict';
var area=[500,200000,50000000], time=[80,12,1.5];
var MARS=144800000; // km^2
console.log("Cloud Seeder Fleet - planetary engineering timelines");
console.log("==================================================");
for(var m=0;m<3;m++){
  var rate=area[m]/time[m]; // km^2 per year
  var marsYears=MARS/rate;
  console.log("Mark "+(m+1)+": "+rate.toExponential(1)+" km^2/yr");
  console.log("  Mars-sized project: ~"+(marsYears>1000?(marsYears/1000).toFixed(1)+"k":marsYears.toFixed(0))+" years at full deployment");
}
console.log("Ecological review and reversibility plans required before any deployment.");

